mapper.select:
select
id, relay_resource_id, target_resource_id, port, protocol, transport, path, security, public_key, sni, short_id,
node_port, is_deleted, create_user, update_user, create_time, update_time, status
from relay_port

    1 = 1 and is_deleted = 0

        and id = #{id}


        and relay_resource_id = #{relayResourceId}


        and target_resource_id = #{targetResourceId}


        and port = #{port}


        and protocol = #{protocol}


        and transport = #{transport}


        and path = #{path}


        and security = #{security}


        and public_key = #{publicKey}


        and sni = #{sni}


        and short_id = #{shortId}


        and node_port = #{nodePort}

select
id, relay_resource_id, target_resource_id, port, protocol, transport, path, security, public_key, sni, short_id,
node_port, is_deleted, create_user, update_user, create_time, update_time, status
from relay_port

    1 = 1 and is_deleted = 0

        and id = #{dto.id}


        and relay_resource_id = #{dto.relayResourceId}


        and target_resource_id = #{dto.targetResourceId}


        and port = #{dto.port}


